GAME_NAMES = {0: "Prisoner's Dilemma", 1: "Battle of the Sexes"}

# Payoff rules exactly as narrated in build_jsonl.py (transcribe_exp0).
RULES = {
    0: (
        "The game is a Prisoner's Dilemma. The rules are:\n"
        "If you choose J and the other player chooses J, you win 8 points and the other wins 8 points.\n"
        "If you choose J and the other player chooses F, you win 0 points and the other wins 10 points.\n"
        "If you choose F and the other player chooses J, you win 10 points and the other wins 0 points.\n"
        "If you choose F and the other player chooses F, you win 5 points and the other wins 5 points."
    ),
    1: (
        "The game is a Battle of the Sexes. The rules are:\n"
        "If you choose J and the other player chooses J, you win 7 points and the other wins 10 points.\n"
        "If you choose J and the other player chooses F, you win 0 points and the other wins 0 points.\n"
        "If you choose F and the other player chooses J, you win 0 points and the other wins 0 points.\n"
        "If you choose F and the other player chooses F, you win 10 points and the other wins 7 points."
    ),
}

LETTER = {0: "F", 1: "J"}          # response coding: 0 = F, 1 = J
GUESSES = ["Human", "LLM"]         # per-game opponent guess options

INSTRUCTIONS = (
    "You are going to play two games against an artificial agent or another fellow "
    "human. Your opponent is randomly assigned and changes at the start of each game. "
    "Your goal is to gain as many points as possible in both games.\n"
    "Each game is a 2x2 game played with 2 players: you and the other player each "
    "choose between two options, Option F and Option J. Each game consists of 10 "
    "rounds. On each round, choose one of the two options by typing F or J "
    "(type F to choose Option F, J to choose Option J). You have 20 seconds to "
    "choose.\n"
    "After each game you will be asked whether you think your opponent was a human "
    "or an artificial agent; answer by typing Human or LLM."
)


def _payoff(block, you, opp):
    """Participant's payoff for (you-move, opponent-move), letters F/J, matching
    the payoff matrices in the paper / task code / build_jsonl.py."""
    if block == 0:  # Prisoner's Dilemma
        if you == "J" and opp == "J":
            return 8
        if you == "J" and opp == "F":
            return 0
        if you == "F" and opp == "J":
            return 10
        return 5
    # Battle of the Sexes
    if you == "J" and opp == "J":
        return 7
    if you == "J" and opp == "F":
        return 0
    if you == "F" and opp == "J":
        return 0
    return 10


class RepeatedGames:
    """Human experiment of Akata et al. (2025), "Playing repeated games with large
    language models", Nature Human Behaviour 9, 1380-1390. See Methods, Human-LLM
    interactions - Design (p. 1387) and fig. 7a.

    Design: each participant plays the Prisoner's Dilemma (block 0) and the Battle
    of the Sexes (block 1), one 10-round game each, order counterbalanced between
    subjects. Each round the participant freely chooses F or J (response 0=F, 1=J,
    fixed mapping, pinned by the instructions); the opponent is GPT-4 (base or
    SCoT-prompted, between-subject, kept across both games) whose move is read from
    the shipped lookup tables keyed on the participant's history within the current
    game, and the per-round reward follows the game's payoff matrix. After each game
    the participant guesses whether the opponent was Human or LLM.

    The DataFrame mirrors exp0.csv (participant_id, task_id, trial, response, block,
    reward, condition, guess, coordination, valid, phase); every recorded round is
    valid (=1). task_id numbers the two games in presentation order and trial
    restarts at 0 in each; each per-game guess is a row of its own (phase ==
    "opponent_guess", response = "Human"/"LLM", reward and coordination empty).
    ``rt`` is not produced by a text simulator and is dropped.

    ASSUMPTION: the opponent's move is read from the shipped lookup tables with the
    participant's base/prompted table fixed for the whole session, as the paper
    describes; the source task code re-drew that table on every round, so a
    simulated session need not re-match the rewards in exp0.csv (a fresh session is
    internally consistent).
    ASSUMPTION: ``coordination`` follows the source analysis coding used in the task
    code (PD: reward == 5; BoS: reward != 0); the published CSV shows a few rows
    deviating from this, but coordination is not part of the transcript text.
    """

    def __init__(self):
        self.name = "akata_2025_playing_exp0"
        self.num_games = 2         # PD (block 0) and BoS (block 1)
        self.num_rounds = 10       # rounds per game

    def simulate(self, agent, num_simulations, max_chars=None):
        rows, prompts = [], []
        for participant in range(num_simulations):
            condition = np.random.choice(["base", "prompted"])
            order = list(range(self.num_games))
            np.random.shuffle(order)
            prompt = INSTRUCTIONS
            history = {0: "", 1: ""}
            for task_id, block in enumerate(order):
                if max_chars is not None and len(prompt) >= max_chars:
                    break
                trial = 0
                prompt += "\n" + RULES[block] + "\nYou will play 10 rounds."
                for round_in_game in range(1, self.num_rounds + 1):
                    prompt += f"\nRound {round_in_game}: you press [HUMAN_RESPONSE]"
                    letter = agent(prompt, choice_options=["F", "J"])
                    prompt += f"{letter}[/HUMAN_RESPONSE]. "
                    table = _LOOKUPS[
                        f"{'pd' if block == 0 else 'bos'}_{condition}"]
                    opp = table.get(history[block])
                    opp = opp if opp in ("F", "J") else str(np.random.choice(["F", "J"]))
                    history[block] += letter
                    reward = _payoff(block, letter, opp)
                    prompt += f"You won {reward} point{'s' if reward != 1 else ''}."
                    coordination = 1 if (reward == 5 if block == 0 else reward != 0) else 0
                    rows.append({
                        "participant_id": participant, "task_id": task_id, "trial": trial,
                        "response": 0 if letter == "F" else 1, "block": block,
                        "reward": reward, "condition": condition,
                        "guess": "Human", "coordination": coordination,
                        "valid": 1, "phase": "game",
                    })
                    trial += 1
                prompt += ("\nWho do you think was your opponent in the previous "
                           "game? You answer [HUMAN_RESPONSE]")
                guess = agent(prompt, choice_options=GUESSES)
                prompt += f"{guess}[/HUMAN_RESPONSE]."
                for r in reversed(rows):
                    if r["participant_id"] == participant and r["block"] == block:
                        r["guess"] = guess
                rows.append({
                    "participant_id": participant, "task_id": task_id, "trial": trial,
                    "response": guess, "block": block,
                    "reward": np.nan, "condition": condition,
                    "guess": guess, "coordination": np.nan,
                    "valid": 1, "phase": "opponent_guess",
                })
                trial += 1
            prompts.append(prompt)
        df = pd.DataFrame(rows, columns=[
            "participant_id", "task_id", "trial", "response", "block", "reward",
            "condition", "guess", "coordination", "valid", "phase",
        ])
        return df, prompts


def _random_agent(prompt, choice_options):
    return str(np.random.choice(choice_options))


def main():
    parser = argparse.ArgumentParser(
        description="Smoke-test this simulator with a uniform-random agent.")
    parser.add_argument("-n", "--num-simulations", type=int, default=3,
                        help="number of simulated participants (default: 3)")
    parser.add_argument("--max-chars", type=int, default=None,
                        help="stop each participant at the block boundary at/past this many chars")
    parser.add_argument("--seed", type=int, default=None,
                        help="numpy random seed, for reproducible runs")
    args = parser.parse_args()

    if args.seed is not None:
        np.random.seed(args.seed)

    task = RepeatedGames()
    df, prompts = task.simulate(_random_agent, args.num_simulations,
                                max_chars=args.max_chars)

    print(f"name: {task.name}")
    print(f"df shape: {df.shape}")
    print("dtypes:")
    print(df.dtypes.to_string())
    print("head:")
    print(df.head(8).to_string())
    print(f"prompt lengths: {[len(p) for p in prompts]}")
    for i, p in enumerate(prompts):
        first = p.splitlines()[0]
        if len(first) > 180:
            first = first[:90] + " ... " + first[-90:]
        print(f"participant {i} first line: {first}")
    print("=" * 78)
    print("first prompt, head:")
    print(prompts[0][:600])
    print("...")
    print("first prompt, tail:")
    print(prompts[0][-300:])


if __name__ == "__main__":
    main()